// A usermod's settings, handed from a settings save to its loop().
//
// WLED applies a Usermods settings save by calling readFromConfig() from the
// web request handler (set.cpp, handleSettingsSet) - on the ESP32 that is the
// AsyncTCP task, running alongside the Arduino loop task. A usermod that
// rewires pins, rewrites the tables loop() reads or talks I2C in
// readFromConfig() does it while loop() may be in the middle of the same thing.
// So readFromConfig() parses the settings into a struct and put()s it here;
// loop() take()s it on its next pass and applies it there, on its own task.
//
// put() waits a little for a take() in progress (the web task can afford it);
// take() never waits (the loop cannot), and finds the settings on a later pass
// instead. On the ESP8266 the web callbacks do not run alongside loop(), and
// the flag alone is enough.
#ifdef ARDUINO_ARCH_ESP32
  #include <freertos/FreeRTOS.h>
  #include <freertos/semphr.h>
#endif

template <typename T>
class CfxHandoff {
 public:
  // Called from setup() - before the first settings save can arrive.
  void begin() {
  #ifdef ARDUINO_ARCH_ESP32
    if (!mx_) mx_ = xSemaphoreCreateMutex();
  #endif
  }

  // The web task: the new settings, for the loop to take. False if the loop
  // held the lock too long (the save is then not applied until the next one).
  bool put(const T &v) {
    if (!lock(pdMS_TO_TICKS_SAFE(200))) return false;
    next_ = v;
    ready_ = true;
    unlock();
    return true;
  }

  // The loop task: true, with `out` filled, when a save is waiting.
  bool take(T &out) {
    if (!ready_ || !lock(0)) return false;
    out = next_;
    ready_ = false;
    unlock();
    return true;
  }

 private:
  T next_{};
  volatile bool ready_ = false;
#ifdef ARDUINO_ARCH_ESP32
  SemaphoreHandle_t mx_ = nullptr;
  static constexpr uint32_t pdMS_TO_TICKS_SAFE(uint32_t ms) { return ms / portTICK_PERIOD_MS; }
  bool lock(uint32_t ticks) { return mx_ && xSemaphoreTake(mx_, ticks) == pdTRUE; }
  void unlock() { xSemaphoreGive(mx_); }
#else
  static constexpr uint32_t pdMS_TO_TICKS_SAFE(uint32_t ms) { return ms; }
  bool lock(uint32_t) { return true; }
  void unlock() {}
#endif
};
